def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    mod = 1_000_000_007
    if n == 0:
        return 1

    children = [{}]
    terminal = [False]
    for word in banned:
        node = 0
        for char in word:
            if char not in children[node]:
                children[node][char] = len(children)
                children.append({})
                terminal.append(False)
            node = children[node][char]
        terminal[node] = True

    from collections import deque

    failure = [0] * len(children)
    queue = deque()
    for char in alphabet:
        if char in children[0]:
            queue.append(children[0][char])
        else:
            children[0][char] = 0

    while queue:
        node = queue.popleft()
        terminal[node] |= terminal[failure[node]]
        for char in alphabet:
            if char in children[node]:
                child = children[node][char]
                failure[child] = children[failure[node]][char]
                queue.append(child)
            else:
                children[node][char] = children[failure[node]][char]

    states = [node for node in range(len(children)) if not terminal[node]]
    index = {node: i for i, node in enumerate(states)}
    size = len(states)
    matrix = [[0] * size for _ in range(size)]

    for node in states:
        row = matrix[index[node]]
        for char in alphabet:
            target = children[node][char]
            if not terminal[target]:
                row[index[target]] += 1

    vector = [0] * size
    vector[index[0]] = 1

    while n:
        if n & 1:
            result = [0] * size
            for i, value in enumerate(vector):
                if value:
                    for j, count in enumerate(matrix[i]):
                        result[j] = (result[j] + value * count) % mod
            vector = result

        n >>= 1
        if n:
            squared = [[0] * size for _ in range(size)]
            for i in range(size):
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, count in enumerate(matrix[k]):
                            squared[i][j] = (
                                squared[i][j] + value * count
                            ) % mod
            matrix = squared

    return sum(vector) % mod
